<script setup>
import {ref,onMounted,computed} from 'vue'
import CodeFrame from '../../../shared/CodeFrame.vue'
import {validatePackage,templateSlots} from '../../../shared/themes.js'
import {designValue} from '../../../shared/siteDesign.js'
const props=defineProps({apiWrite:Function}),emit=defineEmits(['design','pages'])
const rows=ref([]),examples=ref([]),review=ref(null),designRevision=ref(''),busy=ref(false),error=ref(''),notice=ref(''),slot=ref('home'),preview=ref(null)
const kind=computed(()=>review.value?.format==='nova-theme'?'theme':'template')
const previewData=computed(()=>{const d=designValue();return {settings:{name:'Предпросмотр NOVA',shop_enabled:true,blog_enabled:false,menu:[]},products:[],design:{texts:d.texts,colors:{...d.colors,...review.value?.style?.colors},font:review.value?.style?.font||d.font,width:d.width,radius:d.radius},theme:{id:review.value?.manifest.id,settings:Object.fromEntries((review.value?.settings_schema||[]).map(f=>[f.id,f.default]))},route:{path:'/',search:''},context:{page:{title:'Пример страницы',content:'Публичный текст страницы',sections:[]},product:{id:1,name:'Пример товара',description:'Тестовый товар, без отправки заказа',price:100,stock:2,variants:[],image_url:''}},cartSummary:{count:0,total_cents:0}}})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){await run(async()=>{const [list,samples,d]=await Promise.all([props.apiWrite('/api/admin/packages','GET'),props.apiWrite('/api/admin/packages/examples','GET'),props.apiWrite('/api/admin/design','GET')]);rows.value=list;examples.value=samples;designRevision.value=d.revision})}
function inspect(p){review.value=JSON.parse(JSON.stringify(p));slot.value=Object.keys(p.templates||{})[0]||'home';preview.value=null;error.value=''}
async function file(event){const f=event.target.files?.[0];if(!f)return;await run(async()=>{if(f.size>512*1024)throw Error('Файл до 512 КиБ');const p=JSON.parse(await f.text()),invalid=validatePackage(p);if(invalid)throw Error(invalid);inspect(p)});event.target.value=''}
async function open(row){await run(async()=>inspect((await props.apiWrite('/api/admin/packages/'+row.kind+'/'+row.id,'GET')).package))}
async function install(){await run(async()=>{const existing=rows.value.find(r=>r.kind===kind.value&&r.id===review.value.manifest.id);const r=await props.apiWrite('/api/admin/packages','POST',{package:review.value,...(existing?{revision:existing.revision}:{})});rows.value=await props.apiWrite('/api/admin/packages','GET');notice.value='Пакет '+r.manifest.name+' установлен. Оформление сайта пока не изменилось.'})}
async function apply(row){await run(async()=>{const d=await props.apiWrite('/api/admin/themes/'+row.id+'/apply','POST',{design_revision:designRevision.value,package_revision:row.revision});designRevision.value=d.revision;notice.value='Тема применена к черновику. Проверьте настройки в «Оформление и код» и опубликуйте.'})}
function download(p){const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=p.manifest.id+'.nova.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportDraft(){await run(async()=>download(await props.apiWrite('/api/admin/packages/active-export','GET')))}
function showPreview(){preview.value=JSON.parse(JSON.stringify(review.value.templates[slot.value]))}
onMounted(load)
</script>
<template><div class="themes-workspace"><div class="page-title"><div><span class="eyebrow">РАСШИРЕНИЯ NOVA</span><h1>Темы и шаблоны</h1><p>Переносимые пакеты HTML, CSS и JavaScript. Установка и применение в черновик — отдельные действия.</p></div><button class="row-btn" :disabled="busy" @click="load">Обновить список</button></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" class="themes-notice" role="status">{{notice}}</p>
<section class="panel theme-panel"><div class="theme-heading"><h2>Установить пакет</h2><label class="theme-file">Выбрать .nova.json<input type="file" accept="application/json,.json" :disabled="busy" @change="file"></label></div><p>Тема меняет стиль и шаблоны вывода. Шаблон страницы заполняет её секциями. Изучите код неизвестного автора перед предпросмотром и публикацией. PHP, серверный JavaScript, npm-зависимости и архивы не устанавливаются.</p><a href="https://github.com/maxx52/nova-engine/blob/main/docs/THEMES.md" target="_blank" rel="noopener noreferrer">Руководство разработчика на GitHub ↗</a><div class="theme-heading"><button v-for="p in examples" :key="p.manifest.id" class="row-btn" :disabled="busy" @click="inspect(p)">Посмотреть пример: {{p.manifest.name}}</button><button class="row-btn" :disabled="busy" @click="exportDraft">Экспорт темы черновика</button></div></section>
<section v-if="review" class="panel theme-panel"><h2>{{review.manifest.name}} · {{review.manifest.version}}</h2><p>{{review.manifest.description}}</p><p>{{review.format}} · API {{review.apiVersion}} · {{review.manifest.author||'Автор не указан'}} · {{review.manifest.license}}</p><template v-if="kind==='theme'"><p>Шаблоны: {{Object.keys(review.templates).map(k=>templateSlots[k]).join(', ')||'Стандартные шаблоны CMS'}}. Настроек: {{review.settings_schema.length}}.</p><label v-if="Object.keys(review.templates).length">Шаблон для предпросмотра<select v-model="slot" aria-label="Шаблон для предпросмотра" @change="preview=null"><option v-for="(_,name) in review.templates" :key="name" :value="name">{{templateSlots[name]}}</option></select></label><button v-if="Object.keys(review.templates).length" class="row-btn" :disabled="busy" @click="showPreview">Выполнить предпросмотр шаблона</button><p>В предпросмотре — демонстрационные данные. Корзина, формы и чтение API отключены.</p><CodeFrame v-if="preview" :key="JSON.stringify(preview)" :code="preview" :data="previewData" title="Предпросмотр шаблона темы" @error="error=$event"/></template><template v-else><h3>{{review.page.title}}</h3><p>{{review.page.content}}</p><ol><li v-for="s in review.page.sections" :key="s.id">{{s.type==='form'?'Форма: выберите свою в редакторе страницы':s.title||s.type}}</li></ol></template><div class="theme-heading"><button class="primary-btn" :disabled="busy" @click="install">Установить / обновить пакет</button><button class="row-btn" @click="download(review)">Скачать JSON</button><button class="row-btn" @click="review=null;preview=null">Закрыть просмотр</button></div></section>
<section class="panel theme-panel"><h2>Библиотека пакетов</h2><p>Применение темы заменит стиль, настройки и код темы только в черновике. Тексты сайта, товары, страницы, меню и получатели уведомлений сохраняются. Прежний собственный блок будет выключен; состояние до применения доступно в истории оформления.</p><article v-for="row in rows" :key="row.kind+row.id" class="theme-card"><div><h3>{{row.manifest.name}} · {{row.manifest.version}}</h3><p>{{row.kind==='theme'?'Тема':'Шаблон страницы'}} · {{row.id}}</p><p>{{row.manifest.description}}</p></div><div class="theme-heading"><button class="row-btn" :disabled="busy" @click="open(row)">Посмотреть пакет</button><button v-if="row.kind==='theme'" class="primary-btn" :disabled="busy" @click="apply(row)">Применить к черновику</button><button v-else class="row-btn" @click="emit('pages')">Открыть страницы</button></div></article><p v-if="!rows.length" class="empty">Пока нет установленных пакетов.</p><button class="row-btn" @click="emit('design')">Открыть оформление и публикацию</button></section>
</div></template>
<style scoped>.theme-panel{padding:24px;display:grid;gap:16px;margin-bottom:20px;min-width:0}.theme-panel h2,.theme-panel p,.theme-card h3{margin:0}.theme-panel p{font-size:13px;line-height:1.7;color:#5b7264;overflow-wrap:anywhere}.theme-heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.theme-file{font-size:13px;display:grid;gap:8px}.theme-file input{max-width:100%}.theme-card{padding:20px;border:1px solid #d8e4db;border-radius:10px;display:grid;gap:16px}.theme-card h3{font-size:18px}.theme-panel label{display:grid;gap:8px;font-size:13px}.theme-panel select{font:inherit;padding:10px;border:1px solid #d0ded5;border-radius:8px;max-width:100%}.themes-notice{padding:16px;background:#edf7ef;color:#28633d;border-radius:8px}.theme-panel a{color:#246748}.theme-panel button:disabled{opacity:.5}@media(max-width:600px){.theme-panel{padding:16px}}</style>
